AWS API Gateway.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the AWS API Gateway container

Container_Boundary(aws_api_gateway, "AWS API Gateway") {
    Component(Ingress_Traffic_Handler, "Ingress Traffic Handler", "AWS API Gateway / AWS WAF", "Handles ingress traffic and provides AWS WAF rate-limiting to protect against DDoS.")
    Component(JWT_Authorizer, "JWT Authorizer", "AWS API Gateway Native JWT", "Performs native JWT authorizer validation for incoming payment requests.")
}

Rel(Ingress_Traffic_Handler, JWT_Authorizer, "Passes validated payloads", "HTTPS/JSON")

@enduml

Fraud Scoring Engine.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(fraud_scoring_engine, "Fraud Scoring Engine") {
    Component(API_Controller, "API Controller", "Go / Rust", "Receives payment requests from the API Gateway and exposes endpoints for scoring.")
    Component(Feature_Assembler, "Feature Assembler", "Go / Rust", "Queries real-time features from cache to assemble the feature set for evaluation.")
    Component(Evaluation_Core, "Evaluation Core", "Go / Rust", "Applies rules and models to evaluate payment transactions and produce risk scores.")
    Component(Telemetry_Publisher, "Telemetry Publisher", "Go / Rust", "Publishes decision events asynchronously to downstream message queues.")
}

Rel(API_Controller, Feature_Assembler, "Requests real-time feature assembly for incoming payments", "Internal")
Rel(Feature_Assembler, Evaluation_Core, "Passes assembled features for scoring", "Internal")
Rel(Evaluation_Core, Telemetry_Publisher, "Sends decision results for asynchronous publishing", "Internal")

@enduml

Audit & Evidence Worker.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(audit_evidence_worker, "Audit & Evidence Worker") {
    Component(sqs_consumer, "SQS Consumer", "Go", "Polls asynchronous audit events from Amazon SQS.")
    Component(canonicalizer_sanitizer, "Canonicalizer & Sanitizer", "Go", "Normalizes and sanitizes incoming audit event payloads.")
    Component(s3_batch_writer, "S3 Batch Writer", "Go / AWS SDK v2", "Writes immutable audit logs with metadata to AWS S3 with Object Lock.")
    Component(sqs_dlq, "SQS DLQ", "Amazon SQS", "Routes failed writes on persistent errors.")
}

Rel(sqs_consumer, canonicalizer_sanitizer, "Forwards polled audit events")
Rel(canonicalizer_sanitizer, s3_batch_writer, "Sends sanitized records")
Rel(s3_batch_writer, sqs_dlq, "Routes failed writes on persistent errors", "SQS SendMessage")

@startuml

AWS ElastiCache (Redis).diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the AWS ElastiCache (Redis) container

Container_Boundary(aws_elasticache_redis, "AWS ElastiCache (Redis)") {
    Component(RedisCluster, "Redis Cluster", "AWS ElastiCache (Redis) cache.m6g.large", "Provides sub-millisecond feature lookup using cache.m6g.large instances via Redis Protocol (RESP) over TLS.")
}

Component(FraudScoringEngine, "Fraud Scoring Engine", "Go / Rust", "High-throughput, low-latency Fraud Scoring Engine")

Rel(RedisCluster, FraudScoringEngine, "Returns real-time features to", "Redis Protocol (RESP) over TLS")

@enduml

Amazon SQS.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(amazon_sqs, "Amazon SQS") {
    Component(Standard_Queue, "Standard Queue", "AWS SQS Standard", "High-throughput message queue supporting 3,000 TPS for asynchronous audit events.")
    Component(Dead_Letter_Queue_DLQ, "Dead Letter Queue (DLQ)", "AWS SQS DLQ", "Captures failed audit messages and emits metric telemetry to AWS CloudWatch.")
}

Rel(Standard_Queue, Dead_Letter_Queue_DLQ, "Routes failed messages upon processing exhaustion", "")

@enduml
